cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_WIDTH 32

__global__ void matrixMulKernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Row and Column of C that this thread is responsible for
    int row = by * TILE_WIDTH + ty;
    int col = bx * TILE_WIDTH + tx;

    float value = 0.0f;

    // Loop over the A and B tiles required to compute the C element
    for (int m = 0; m < (K + TILE_WIDTH - 1) / TILE_WIDTH; ++m) {
        // Shared memory for the sub-matrix of A and B
        __shared__ float ds_A[TILE_WIDTH][TILE_WIDTH];
        __shared__ float ds_B[TILE_WIDTH][TILE_WIDTH];

        // Load A into shared memory
        // A[row][m*TILE_WIDTH + tx]
        if (row < M && (m * TILE_WIDTH + tx) < K) {
            ds_A[ty][tx] = A[row * K + m * TILE_WIDTH + tx];
        } else {
            ds_A[ty][tx] = 0.0f;
        }

        // Load B into shared memory
        // B[m*TILE_WIDTH + ty][col]
        if ((m * TILE_WIDTH + ty) < K && col < N) {
            ds_B[ty][tx] = B[(m * TILE_WIDTH + ty) * N + col];
        } else {
            ds_B[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Multiply the sub-matrices
        #pragma unroll
        for (int k = 0; k < TILE_WIDTH; ++k) {
            value += ds_A[ty][k] * ds_B[k][tx];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = value;
    }
}

torch::Tensor matmul_custom(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 dimBlock(TILE_WIDTH, TILE_WIDTH);
    dim3 dimGrid((N + TILE_WIDTH - 1) / TILE_WIDTH, (M + TILE_WIDTH - 1) / TILE_WIDTH);

    matrixMulKernel<<<dimGrid, dimBlock>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}
"""

module = load_inline(
    name="custom_matmul",
    cpp_sources=cpp_source,
    functions=["matmul_custom"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.module = module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.module.matmul_custom(A, B)

