cpp_source = """
#include <hip/hip_runtime.h>

#define ROWS_PER_BLOCK 4
#define BLOCK_SIZE 256

__global__ void gemv_kernel_opt(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int K) {
    int block_row_start = blockIdx.x * ROWS_PER_BLOCK;

    // Output accumulators
    float sum[ROWS_PER_BLOCK];
    #pragma unroll
    for (int i = 0; i < ROWS_PER_BLOCK; ++i) {
        sum[i] = 0.0f;
    }

    // Shared memory for reduction
    __shared__ float sdata[ROWS_PER_BLOCK][BLOCK_SIZE];

    int tid = threadIdx.x;

    // Vectorized loads using float4
    // Assumes K is multiple of 4 and pointers are aligned
    const float4* B_vec = reinterpret_cast<const float4*>(B);
    const float4* A_vec = reinterpret_cast<const float4*>(A);

    int K_vec = K / 4;

    for (int k = tid; k < K_vec; k += BLOCK_SIZE) {
        float4 b_val = B_vec[k];

        #pragma unroll
        for (int i = 0; i < ROWS_PER_BLOCK; ++i) {
            int current_row = block_row_start + i;
            if (current_row < M) {
                // A is row-major. Row start is current_row * K
                // In float4 elements, row start is current_row * K_vec

                size_t offset = (size_t)current_row * K_vec + k;
                float4 a_val = A_vec[offset];

                sum[i] += a_val.x * b_val.x;
                sum[i] += a_val.y * b_val.y;
                sum[i] += a_val.z * b_val.z;
                sum[i] += a_val.w * b_val.w;
            }
        }
    }

    // Store sums to shared memory
    #pragma unroll
    for (int i = 0; i < ROWS_PER_BLOCK; ++i) {
        sdata[i][tid] = sum[i];
    }
    __syncthreads();

    // Parallel reduction in shared memory
    for (int s = BLOCK_SIZE / 2; s > 0; s >>= 1) {
        if (tid < s) {
            #pragma unroll
            for (int i = 0; i < ROWS_PER_BLOCK; ++i) {
                sdata[i][tid] += sdata[i][tid + s];
            }
        }
        __syncthreads();
    }

    if (tid == 0) {
        #pragma unroll
        for (int i = 0; i < ROWS_PER_BLOCK; ++i) {
            int current_row = block_row_start + i;
            if (current_row < M) {
                C[current_row] = sdata[i][0];
            }
        }
    }
}

torch::Tensor gemv_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::zeros({M, 1}, A.options());

    dim3 block(BLOCK_SIZE);
    dim3 grid((M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK);

    gemv_kernel_opt<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, K);

    return C;
}
"""

gemv_module = load_inline(
