#include <hip/hip_runtime.h>
#include <cfloat>

#define K_SIZE 4
#define STRIDE 1
#define PAD 1
#define DILATION 1

__global__ void maxpool_fixed_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int channels_total,
    const int height,
    const int width,
    const int out_height,
    const int out_width
) {
    const int w_out = blockIdx.x * blockDim.x + threadIdx.x;
    const int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    const int c_idx = blockIdx.z;

    if (w_out >= out_width || h_out >= out_height || c_idx >= channels_total) {
        return;
    }

    // Calculate offsets
    // input shape: (N*C, H, W) effectively
    const int input_slice_start = c_idx * height * width;
    const int output_idx = c_idx * out_height * out_width + h_out * out_width + w_out;

    const float* in_ptr = input + input_slice_start;

    float max_val = -FLT_MAX;

    #pragma unroll
    for (int kh = 0; kh < K_SIZE; ++kh) {
        #pragma unroll
        for (int kw = 0; kw < K_SIZE; ++kw) {
            int h_in = h_out * STRIDE - PAD + kh * DILATION;
            int w_in = w_out * STRIDE - PAD + kw * DILATION;

            if (h_in >= 0 && h_in < height && w_in >= 0 && w_in < width) {
                float val = in_ptr[h_in * width + w_in];
                max_val = fmaxf(max_val, val);
            }
        }
    }

    output[output_idx] = max_val;
}

torch::Tensor maxpool_hip(torch::Tensor input) {
    const int batch = input.size(0);
    const int channels = input.size(1);
    const int height = input.size(2);
    const int width = input.size(3);

    const int out_height = (height + 2 * PAD - DILATION * (K_SIZE - 1) - 1) / STRIDE + 1;
    const int out_width = (width + 2 * PAD - DILATION * (K_SIZE - 1) - 1) / STRIDE + 1;

    auto output = torch::empty({batch, channels, out_height, out_width}, input.options());

    // Block dimensions: 32x8 covers a 32x8 region of the image
    dim3 block(32, 8);
    dim3 grid(
        (out_width + block.x - 1) / block.x,
        (out_height + block.y - 1) / block.y,
        batch * channels
    );

    maxpool_fixed_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch * channels,
        height,
        width,
        out_height,
        out_width
    );

    return output;
}
