#include <hip/hip_runtime.h>

__global__ void sum_reduce_dim1_kernel(const float* __restrict__ input, 
                                       float* __restrict__ output, 
                                       int B, int D1, int D2) {
    // Grid x -> D2, Grid y -> B
    // d2 maps to the last dimension
    // b maps to the batch dimension
    long long d2 = blockIdx.x * blockDim.x + threadIdx.x;
    long long b = blockIdx.y;

    if (d2 < D2 && b < B) {
        // Calculate base index
        // Input shape (B, D1, D2)
        // flattened index = b * (D1 * D2) + k * D2 + d2
        // We iterate k from 0 to D1-1

        long long stride = D2;
        // Cast to long long to prevent overflow since B*D1*D2 can be > 2^31
        long long input_idx = b * (long long)D1 * D2 + d2;

        float sum = 0.0f;

        #pragma unroll 4
        for (int k = 0; k < D1; ++k) {
            sum += input[input_idx];
            input_idx += stride;
        }

        // Output shape (B, 1, D2) -> flattened (B, D2)
        // index = b * D2 + d2
        output[b * (long long)D2 + d2] = sum;
    }
}

torch::Tensor sum_reduce_dim1(torch::Tensor input) {
    int B = input.size(0);
    int D1 = input.size(1);
    int D2 = input.size(2);

    auto output = torch::empty({B, 1, D2}, input.options());

    int threads_per_block = 256;
    // Ensure D2 is covered
    int blocks_x = (D2 + threads_per_block - 1) / threads_per_block;
    int blocks_y = B;

    dim3 blocks(blocks_x, blocks_y);
    dim3 threads(threads_per_block);

    sum_reduce_dim1_kernel<<<blocks, threads, 0, torch::hip::getCurrentHIPStream()>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        B, D1, D2
    );

    return output;
}
"""

module = load_inline(
    name="sum_reduce_kernels",
    cpp_sources=cpp_source,
    functions=["sum_reduce_dim1"],
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.sum_reduce = module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Check for specific optimization case: dim=1 and 3D tensor
        if self.dim == 1 and x.dim() == 3:
            return self.sum_reduce.sum_reduce_dim1(x)

        # Fallback
        return torch.sum(x, dim=self.dim, keepdim=True)

