conv2d_source = """
#include <hip/hip_runtime.h>

#define TILE_H 8
#define TILE_W 32
#define BLOCK_K 16
#define IN_C 16
#define KERNEL_SIZE 3

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weights,
    float* __restrict__ output,
    int batch_size,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int out_channels
) {
    int k_chunks = out_channels / BLOCK_K;
    int n = blockIdx.z / k_chunks;
    int k_block = blockIdx.z % k_chunks;
    int k_start = k_block * BLOCK_K;

    int h_start = blockIdx.y * TILE_H;
    int w_start = blockIdx.x * TILE_W;

    int tid = threadIdx.x;

    // Shared memory
    __shared__ float s_input[IN_C][TILE_H + KERNEL_SIZE - 1][TILE_W + KERNEL_SIZE - 1];
    __shared__ float s_weights[BLOCK_K][IN_C][KERNEL_SIZE][KERNEL_SIZE];

    // Load Input
    int input_tile_h = TILE_H + KERNEL_SIZE - 1;
    int input_tile_w = TILE_W + KERNEL_SIZE - 1;
    int total_input_elements = IN_C * input_tile_h * input_tile_w;

    for (int i = tid; i < total_input_elements; i += blockDim.x) {
        int c = i / (input_tile_h * input_tile_w);
        int rem = i % (input_tile_h * input_tile_w);
        int y = rem / input_tile_w;
        int x = rem % input_tile_w;

        int in_y = h_start + y;
        int in_x = w_start + x;

        if (in_y < in_h && in_x < in_w) {
            size_t idx = (size_t)n * (IN_C * in_h * in_w) + (size_t)c * (in_h * in_w) + (size_t)in_y * in_w + in_x;
            s_input[c][y][x] = input[idx];
        } else {
            s_input[c][y][x] = 0.0f;
        }
    }

    // Load Weights
    int total_weight_elements = BLOCK_K * IN_C * KERNEL_SIZE * KERNEL_SIZE;

    for (int i = tid; i < total_weight_elements; i += blockDim.x) {
        int k_local = i / (IN_C * KERNEL_SIZE * KERNEL_SIZE);
        int rem = i % (IN_C * KERNEL_SIZE * KERNEL_SIZE);
        int c = rem / (KERNEL_SIZE * KERNEL_SIZE);
        int rem2 = rem % (KERNEL_SIZE * KERNEL_SIZE);
        int r = rem2 / KERNEL_SIZE;
        int s = rem2 % KERNEL_SIZE;

        int k_global = k_start + k_local;

        if (k_global < out_channels) {
             size_t idx = (size_t)k_global * (IN_C * KERNEL_SIZE * KERNEL_SIZE) + (size_t)c * (KERNEL_SIZE * KERNEL_SIZE) + r * KERNEL_SIZE + s;
             s_weights[k_local][c][r][s] = weights[idx];
        } else {
             s_weights[k_local][c][r][s] = 0.0f;
        }
    }

    __syncthreads();

    // Compute
    int local_y = tid / TILE_W;
    int local_x = tid % TILE_W;

    if (local_y < TILE_H && local_x < TILE_W) {
        int out_y = h_start + local_y;
        int out_x = w_start + local_x;

        float acc[BLOCK_K];
        #pragma unroll
        for (int k = 0; k < BLOCK_K; ++k) acc[k] = 0.0f;

        // Only compute if within output bounds
        if (out_y < out_h && out_x < out_w) {
            for (int c = 0; c < IN_C; ++c) {
                #pragma unroll
                for (int r = 0; r < KERNEL_SIZE; ++r) {
                    #pragma unroll
                    for (int s = 0; s < KERNEL_SIZE; ++s) {
                        float val = s_input[c][local_y + r][local_x + s];
                        #pragma unroll
                        for (int k = 0; k < BLOCK_K; ++k) {
                            acc[k] += val * s_weights[k][c][r][s];
                        }
                    }
                }
            }

            // Store result
            size_t out_pixel_offset = (size_t)out_y * out_w + out_x;
            size_t batch_offset = (size_t)n * (out_channels * out_h * out_w);

            #pragma unroll
            for (int k = 0; k < BLOCK_K; ++k) {
                int k_global = k_start + k;
                if (k_global < out_channels) {
                    size_t out_idx = batch_offset + (size_t)k_global * (out_h * out_w) + out_pixel_offset;
                    output[out_idx] = acc[k];
                }
            }
        }
    }
}

torch::Tensor conv2d_hip(torch::Tensor input, torch::Tensor weights) {
    auto N = input.size(0);
    auto H = input.size(2);
    auto W = input.size(3);
    auto K = weights.size(0);

    auto H_out = H - 2;
    auto W_out = W - 2;

    auto output = torch::empty({N, K, H_out, W_out}, input.options());

    int block_k = 16;
    int tile_h = 8;
    int tile_w = 32;

    int k_chunks = (K + block_k - 1) / block_k;

    dim3 block(256);
    dim3 grid(
        (W_out + tile_w - 1) / tile_w,
        (H_out + tile_h - 1) / tile_h,
        N * k_chunks
    );

    conv2d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weights.data_ptr<float>(),
        output.data_ptr<float>(),
        N, H, W, H_out, W_out, K
    );

    return output;
}
"""

