cpp_source = """
#include <hip/hip_runtime.h>

#define BM 64
#define BN 64
#define BK 16
#define TM 4
#define TN 4

__global__ void matmul_optimized(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;

    // Shared memory with padding to avoid bank conflicts
    __shared__ float As[BM][BK + 1];
    __shared__ float Bs[BK][BN + 1];

    // Registers for accumulation
    float thread_C[TM][TN] = {0.0f};

    // Registers for loading from shared
    float a_reg[TM];
    float b_reg[TN];

    // Indices for loading from global memory
    // Threads load 1 float4 from A and 1 float4 from B per step
    int load_a_row = tid / 4;
    int load_a_col = (tid % 4) * 4;
    int load_b_row = tid / 16;
    int load_b_col = (tid % 16) * 4;

    // Base pointers
    const float* A_ptr = A + by * BM * N;
    // B_ptr will be calculated dynamically

    for (int k = 0; k < N; k += BK) {
        // Vectorized load from A
        float4 a_val = *reinterpret_cast<const float4*>(&A_ptr[load_a_row * N + k + load_a_col]);
        As[load_a_row][load_a_col + 0] = a_val.x;
        As[load_a_row][load_a_col + 1] = a_val.y;
        As[load_a_row][load_a_col + 2] = a_val.z;
        As[load_a_row][load_a_col + 3] = a_val.w;

        // Vectorized load from B
        // Address: B[(k + load_b_row)*N + bx*BN + load_b_col]
        float4 b_val = *reinterpret_cast<const float4*>(&B[(k + load_b_row) * N + bx * BN + load_b_col]);
        Bs[load_b_row][load_b_col + 0] = b_val.x;
        Bs[load_b_row][load_b_col + 1] = b_val.y;
        Bs[load_b_row][load_b_col + 2] = b_val.z;
        Bs[load_b_row][load_b_col + 3] = b_val.w;

        __syncthreads();

        // Compute
        #pragma unroll
        for (int l = 0; l < BK; ++l) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                a_reg[i] = As[ty * TM + i][l];
            }
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                b_reg[j] = Bs[l][tx * TN + j];
            }
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    thread_C[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }

        __syncthreads();
    }

    // Store results
    int c_row = by * BM + ty * TM;
    int c_col = bx * BN + tx * TN;

    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        float4 c_val;
        c_val.x = thread_C[i][0];
        c_val.y = thread_C[i][1];
        c_val.z = thread_C[i][2];
        c_val.w = thread_C[i][3];
        *reinterpret_cast<float4*>(&C[(c_row + i) * N + c_col]) = c_val;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());

    dim3 block(16, 16);
    dim3 grid(N / BN, N / BM);

    matmul_optimized<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
