matmul_source = """
#include <hip/hip_runtime.h>

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tid = threadIdx.x;

    // Block size 256 threads
    // Map tid to (ty, tx) for the 16x16 grid of threads
    // Each thread computes 8x8 elements of C
    // Total coverage: (16*8) x (16*8) = 128 x 128
    int ty = tid / 16;
    int tx = tid % 16;

    __shared__ float As[BM][BK];
    __shared__ float Bs[BK][BN];

    float c_reg[TM][TN];
    float a_reg[TM];
    float b_reg[TN];

    #pragma unroll
    for(int i=0; i<TM; ++i) {
        #pragma unroll
        for(int j=0; j<TN; ++j) {
            c_reg[i][j] = 0.0f;
        }
    }

    int num_tiles = (K + BK - 1) / BK;

    for (int t = 0; t < num_tiles; ++t) {
        // Load A: BM x BK = 128 x 8 = 1024 floats
        // Threads: 256. Each loads 4 floats.
        #pragma unroll
        for(int i=0; i<4; ++i) {
            int idx = tid + i * 256;
            int r = idx / BK; // 0..127
            int c = idx % BK; // 0..7

            int global_r = by * BM + r;
            int global_c = t * BK + c;

            if (global_r < M && global_c < K) {
                As[r][c] = A[global_r * K + global_c];
            } else {
                As[r][c] = 0.0f;
            }
        }

        // Load B: BK x BN = 8 x 128 = 1024 floats
        // Threads: 256. Each loads 4 floats.
        #pragma unroll
        for(int i=0; i<4; ++i) {
            int idx = tid + i * 256;
            int r = idx / BN; // 0..7
            int c = idx % BN; // 0..127

            int global_r = t * BK + r;
            int global_c = bx * BN + c;

            if (global_r < K && global_c < N) {
                Bs[r][c] = B[global_r * N + global_c];
            } else {
                Bs[r][c] = 0.0f;
            }
        }

        __syncthreads();

        // Compute
        #pragma unroll
        for(int k=0; k<BK; ++k) {
            // Load from shared to registers
            #pragma unroll
            for(int i=0; i<TM; ++i) {
                a_reg[i] = As[ty*TM + i][k];
            }
            #pragma unroll
            for(int j=0; j<TN; ++j) {
                b_reg[j] = Bs[k][tx*TN + j];
            }

            // Outer product
            #pragma unroll
            for(int i=0; i<TM; ++i) {
                #pragma unroll
                for(int j=0; j<TN; ++j) {
                    c_reg[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }

        __syncthreads();
    }

    // Store C
    #pragma unroll
    for(int i=0; i<TM; ++i) {
        int global_r = by * BM + ty * TM + i;
        if (global_r < M) {
            #pragma unroll
            for(int j=0; j<TN; ++j) {
                int global_c = bx * BN + tx * TN + j;
                if (global_c < N) {
                    C[global_r * N + global_c] = c_reg[i][j];
                }
            }
        }
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    dim3 block(256);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);

    matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}
"""

