#include <hip/hip_runtime.h>

#define M_BLK 128
#define N_BLK 128
#define K_BLK 16

__global__ void __launch_bounds__(256) bmm_kernel_128(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, 
                           int m, int n, int k) {

    int batch_idx = blockIdx.z;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    long long batch_offset_A = (long long)batch_idx * m * k;
    long long batch_offset_B = (long long)batch_idx * k * n;
    long long batch_offset_C = (long long)batch_idx * m * n;

    const float* A_ptr = A + batch_offset_A;
    const float* B_ptr = B + batch_offset_B;
    float* C_ptr = C + batch_offset_C;

    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int tx = threadIdx.x; // 0..15
    int ty = threadIdx.y; // 0..15

    __shared__ float As[M_BLK][K_BLK];
    __shared__ float Bs[K_BLK][N_BLK];

    float c_reg[8][8];
    #pragma unroll
    for(int i=0; i<8; ++i) {
        #pragma unroll
        for(int j=0; j<8; ++j) {
            c_reg[i][j] = 0.0f;
        }
    }

    // Load A setup
    int a_idx1 = tid;
    int a_row1 = a_idx1 / 4;
    int a_col1 = (a_idx1 % 4) * 4;

    int a_idx2 = tid + 256;
    int a_row2 = a_idx2 / 4;
    int a_col2 = (a_idx2 % 4) * 4;

    // Load B setup
    int b_idx1 = tid;
    int b_row1 = b_idx1 / 32;
    int b_col1 = (b_idx1 % 32) * 4;

    int b_idx2 = tid + 256;
    int b_row2 = b_idx2 / 32;
    int b_col2 = (b_idx2 % 32) * 4;

    const float* A_base = A_ptr + (by * M_BLK) * k;
    const float* B_base = B_ptr + (bx * N_BLK);

    // Loop over K
    for (int k_idx = 0; k_idx < k; k_idx += K_BLK) {

        // Load A
        float4 a1 = *reinterpret_cast<const float4*>(A_base + a_row1 * k + (k_idx + a_col1));
        As[a_row1][a_col1 + 0] = a1.x;
        As[a_row1][a_col1 + 1] = a1.y;
        As[a_row1][a_col1 + 2] = a1.z;
        As[a_row1][a_col1 + 3] = a1.w;

        float4 a2 = *reinterpret_cast<const float4*>(A_base + a_row2 * k + (k_idx + a_col2));
        As[a_row2][a_col2 + 0] = a2.x;
        As[a_row2][a_col2 + 1] = a2.y;
        As[a_row2][a_col2 + 2] = a2.z;
        As[a_row2][a_col2 + 3] = a2.w;

        // Load B
        float4 b1 = *reinterpret_cast<const float4*>(B_base + (k_idx + b_row1) * n + b_col1);
        Bs[b_row1][b_col1 + 0] = b1.x;
        Bs[b_row1][b_col1 + 1] = b1.y;
        Bs[b_row1][b_col1 + 2] = b1.z;
        Bs[b_row1][b_col1 + 3] = b1.w;

        float4 b2 = *reinterpret_cast<const float4*>(B_base + (k_idx + b_row2) * n + b_col2);
        Bs[b_row2][b_col2 + 0] = b2.x;
        Bs[b_row2][b_col2 + 1] = b2.y;
        Bs[b_row2][b_col2 + 2] = b2.z;
        Bs[b_row2][b_col2 + 3] = b2.w;

        __syncthreads();

        // Compute
        #pragma unroll
        for (int kk = 0; kk < K_BLK; ++kk) {
            float a_c[8];
            float b_c[8];

            #pragma unroll
            for(int i=0; i<8; ++i) {
                a_c[i] = As[ty + i * 16][kk];
            }
            #pragma unroll
            for(int j=0; j<8; ++j) {
                b_c[j] = Bs[kk][tx + j * 16];
            }

            #pragma unroll
            for(int i=0; i<8; ++i) {
                #pragma unroll
                for(int j=0; j<8; ++j) {
                    c_reg[i][j] += a_c[i] * b_c[j];
                }
            }
        }
        __syncthreads();
    }

    // Store C
    int row_start = by * M_BLK + ty;
    int col_start = bx * N_BLK + tx;

    #pragma unroll
    for(int i=0; i<8; ++i) {
        int r = row_start + i * 16;
        #pragma unroll
        for(int j=0; j<8; ++j) {
            int c = col_start + j * 16;
            if(r < m && c < n) {
                C_ptr[r * n + c] = c_reg[i][j];
            }
        }
    }
}

