#include <hip/hip_runtime.h>
#include <cmath>

__global__ void __launch_bounds__(256) gelu_kernel_vec4(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int vec_size = size / 4;

    if (idx < vec_size) {
        const float4* x_ptr = reinterpret_cast<const float4*>(x);
        float4* out_ptr = reinterpret_cast<float4*>(out);

        float4 v = x_ptr[idx];
        float4 r;

        // Use normcdff for optimization: GELU(x) = x * Phi(x)
        r.x = v.x * normcdff(v.x);
        r.y = v.y * normcdff(v.y);
        r.z = v.z * normcdff(v.z);
        r.w = v.w * normcdff(v.w);

        out_ptr[idx] = r;
    }
}

__global__ void gelu_kernel_scalar(const float* __restrict__ x, float* __restrict__ out, int size, int offset) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x + offset;
    if (idx < size) {
        float v = x[idx];
        out[idx] = v * normcdff(v);
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    // x is assumed to be contiguous from get_inputs
    if (!x.is_contiguous()) {
        x = x.contiguous();
    }

    auto size = x.numel();
    auto out = torch::empty_like(x);

    int vec_size = size / 4;
    int remainder = size % 4;

    const int block_size = 256;

    if (vec_size > 0) {
        int num_blocks = (vec_size + block_size - 1) / block_size;
        gelu_kernel_vec4<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    }

    if (remainder > 0) {
        int offset = vec_size * 4;
        gelu_kernel_scalar<<<1, remainder>>>(x.data_ptr<float>(), out.data_ptr<float>(), size, offset);
    }

    return out;
}
"""

