#include <hip/hip_runtime.h>

#define BM 128
#define BN 128
#define BK 16
#define TM 8
#define TN 8

__global__ void matmul_opt_8x8(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * 16 + tx; 

    // 128x128 tile. 
    // Shared memory: As[128][16], Bs[16][128]
    __shared__ float As[BM][BK + 1]; // 128x17
    __shared__ float Bs[BK][BN + 1]; // 16x129

    float thread_C[TM][TN] = {0.0f};
    float a_reg[TM];
    float b_reg[TN];

    // Indices for loading
    // A: 128 rows, 16 cols. 4 float4 per row. 
    // Total 512 vectors. 256 threads. 2 vectors per thread.
    int a_vec = tid * 2;
    int load_a_row_0 = a_vec / 4;
    int load_a_col_0 = (a_vec % 4) * 4;
    int load_a_row_1 = (a_vec + 1) / 4;
    int load_a_col_1 = ((a_vec + 1) % 4) * 4;

    // B: 16 rows, 128 cols. 32 float4 per row.
    // Total 512 vectors.
    int b_vec = tid * 2;
    int load_b_row_0 = b_vec / 32;
    int load_b_col_0 = (b_vec % 32) * 4;
    int load_b_row_1 = (b_vec + 1) / 32;
    int load_b_col_1 = ((b_vec + 1) % 32) * 4;

    const float* A_base = A + by * BM * N;
    // B base dynamic

    for (int k = 0; k < N; k += BK) {
        // Load A
        float4 a0 = *reinterpret_cast<const float4*>(&A_base[load_a_row_0 * N + k + load_a_col_0]);
        As[load_a_row_0][load_a_col_0 + 0] = a0.x;
        As[load_a_row_0][load_a_col_0 + 1] = a0.y;
        As[load_a_row_0][load_a_col_0 + 2] = a0.z;
        As[load_a_row_0][load_a_col_0 + 3] = a0.w;

        float4 a1 = *reinterpret_cast<const float4*>(&A_base[load_a_row_1 * N + k + load_a_col_1]);
        As[load_a_row_1][load_a_col_1 + 0] = a1.x;
        As[load_a_row_1][load_a_col_1 + 1] = a1.y;
        As[load_a_row_1][load_a_col_1 + 2] = a1.z;
        As[load_a_row_1][load_a_col_1 + 3] = a1.w;

        // Load B
        // Address: B[(k + row) * N + bx * BN + col]
        float4 b0 = *reinterpret_cast<const float4*>(&B[(k + load_b_row_0) * N + bx * BN + load_b_col_0]);
        Bs[load_b_row_0][load_b_col_0 + 0] = b0.x;
        Bs[load_b_row_0][load_b_col_0 + 1] = b0.y;
        Bs[load_b_row_0][load_b_col_0 + 2] = b0.z;
        Bs[load_b_row_0][load_b_col_0 + 3] = b0.w;

        float4 b1 = *reinterpret_cast<const float4*>(&B[(k + load_b_row_1) * N + bx * BN + load_b_col_1]);
        Bs[load_b_row_1][load_b_col_1 + 0] = b1.x;
        Bs[load_b_row_1][load_b_col_1 + 1] = b1.y;
        Bs[load_b_row_1][load_b_col_1 + 2] = b1.z;
        Bs[load_b_row_1][load_b_col_1 + 3] = b1.w;

        __syncthreads();

        #pragma unroll
        for (int l = 0; l < BK; ++l) {
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                a_reg[i] = As[ty * TM + i][l];
            }
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                b_reg[j] = Bs[l][tx * TN + j];
            }
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    thread_C[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }
        __syncthreads();
    }

    int c_row = by * BM + ty * TM;
    int c_col = bx * BN + tx * TN;

    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        float4 c0, c1;
        c0.x = thread_C[i][0]; c0.y = thread_C[i][1]; c0.z = thread_C[i][2]; c0.w = thread_C[i][3];
        c1.x = thread_C[i][4]; c1.y = thread_C[i][5]; c1.z = thread_C[i][6]; c1.w = thread_C[i][7];

        *reinterpret_cast<float4*>(&C[(c_row + i) * N + c_col]) = c0;
        *reinterpret_cast<float4*>(&C[(c_row + i) * N + c_col + 4]) = c1;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());

    dim3 block(16, 16);
    dim3 grid(N / BN, N / BM);

    matmul_opt_8x8<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
