#include <hip/hip_runtime.h>

#define BM 128
#define BN 128
#define BK 16
#define TM 8
#define TN 8
#define BK_PAD 20

__global__ void sgemm_128x128(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;

    __shared__ float As[BM][BK_PAD];
    __shared__ float Bs[BK][BN];

    float c_reg[TM][TN] = {0.0f};
    float a_reg[TM];
    float b_reg[TN];

    const float* A_ptr = A + by * BM * K;
    const float* B_ptr = B + bx * BN;

    for (int k = 0; k < K; k += BK) {
        // Load A: 2 float4s per thread
        #pragma unroll
        for (int l = 0; l < 2; ++l) {
            int f4_idx = tid * 2 + l;
            int flat_idx = f4_idx * 4;
            int row = flat_idx / BK; 
            int col = flat_idx % BK;

            float4 vec = *reinterpret_cast<const float4*>(&A_ptr[row * K + k + col]);
            *reinterpret_cast<float4*>(&As[row][col]) = vec;
        }

        // Load B: 2 float4s per thread
        #pragma unroll
        for (int l = 0; l < 2; ++l) {
            int f4_idx = tid * 2 + l;
            int flat_idx = f4_idx * 4;
            int row = flat_idx / BN;
            int col = flat_idx % BN;

            float4 vec = *reinterpret_cast<const float4*>(&B_ptr[(k + row) * N + col]);
            *reinterpret_cast<float4*>(&Bs[row][col]) = vec;
        }

        __syncthreads();

        #pragma unroll
        for (int i = 0; i < BK; ++i) {
            #pragma unroll
            for (int r = 0; r < TM; ++r) {
                a_reg[r] = As[ty * TM + r][i];
            }

            *reinterpret_cast<float4*>(&b_reg[0]) = *reinterpret_cast<float4*>(&Bs[i][tx * TN]);
            *reinterpret_cast<float4*>(&b_reg[4]) = *reinterpret_cast<float4*>(&Bs[i][tx * TN + 4]);

            #pragma unroll
            for (int r = 0; r < TM; ++r) {
                #pragma unroll
                for (int c = 0; c < TN; ++c) {
                    c_reg[r][c] += a_reg[r] * b_reg[c];
                }
            }
        }

        __syncthreads();
    }

    int c_global_row = by * BM + ty * TM;
    int c_global_col = bx * BN + tx * TN;

    #pragma unroll
    for (int r = 0; r < TM; ++r) {
        float4 vec1, vec2;
        vec1.x = c_reg[r][0]; vec1.y = c_reg[r][1]; vec1.z = c_reg[r][2]; vec1.w = c_reg[r][3];
        vec2.x = c_reg[r][4]; vec2.y = c_reg[r][5]; vec2.z = c_reg[r][6]; vec2.w = c_reg[r][7];

        *reinterpret_cast<float4*>(&C[(c_global_row + r) * N + c_global_col]) = vec1;
        *reinterpret_cast<float4*>(&C[(c_global_row + r) * N + c_global_col + 4]) = vec2;
    }
}

