#include <hip/hip_runtime.h>
#include <cmath>

#define SQRT_1_2 0.70710678118654752440f

__global__ void __launch_bounds__(256) gelu_kernel_vec8(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int vec_size = size / 8;

    if (idx < vec_size) {
        const float4* x_ptr = reinterpret_cast<const float4*>(x);
        float4* out_ptr = reinterpret_cast<float4*>(out);

        int base_idx = idx * 2;
        float4 v1 = x_ptr[base_idx];
        float4 v2 = x_ptr[base_idx + 1];

        float4 r1, r2;

        // Process v1
        r1.x = 0.5f * v1.x * (1.0f + erff(v1.x * SQRT_1_2));
        r1.y = 0.5f * v1.y * (1.0f + erff(v1.y * SQRT_1_2));
        r1.z = 0.5f * v1.z * (1.0f + erff(v1.z * SQRT_1_2));
        r1.w = 0.5f * v1.w * (1.0f + erff(v1.w * SQRT_1_2));

        // Process v2
        r2.x = 0.5f * v2.x * (1.0f + erff(v2.x * SQRT_1_2));
        r2.y = 0.5f * v2.y * (1.0f + erff(v2.y * SQRT_1_2));
        r2.z = 0.5f * v2.z * (1.0f + erff(v2.z * SQRT_1_2));
        r2.w = 0.5f * v2.w * (1.0f + erff(v2.w * SQRT_1_2));

        out_ptr[base_idx] = r1;
        out_ptr[base_idx + 1] = r2;
    }
}

// Scalar kernel for remainder
__global__ void gelu_kernel_scalar(const float* __restrict__ x, float* __restrict__ out, int size, int offset) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x + offset;
    if (idx < size) {
        float v = x[idx];
        out[idx] = 0.5f * v * (1.0f + erff(v * SQRT_1_2));
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    if (!x.is_contiguous()) {
        x = x.contiguous();
    }

    auto size = x.numel();
    auto out = torch::empty_like(x);

    int vec_size = size / 8;
    int remainder = size % 8;

    const int block_size = 256;

    if (vec_size > 0) {
        int num_blocks = (vec_size + block_size - 1) / block_size;
        gelu_kernel_vec8<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    }

    if (remainder > 0) {
        int offset = vec_size * 8;
        gelu_kernel_scalar<<<1, remainder>>>(x.data_ptr<float>(), out.data_ptr<float>(), size, offset);
    }

    return out;
}
"""

gelu_module = load_inline(
    name="gelu_module_v3",
