#include <hip/hip_runtime.h>

__global__ void __launch_bounds__(256) sum_reduce_dim1_kernel(const float* __restrict__ input, 
                                       float* __restrict__ output, 
                                       int B, int D1, int D2) {
    long long d2 = blockIdx.x * blockDim.x + threadIdx.x;
    long long b = blockIdx.y;

    if (d2 < D2 && b < B) {
        long long stride = D2;
        // Cast to long long to avoid overflow in intermediate calculation
        // D1*D2 ~ 16M, b ~ 128. b*D1*D2 ~ 2B. Close to int32 limit. 
        // Just to be safe, compute in 64-bit.
        long long input_idx = b * (long long)D1 * D2 + d2;

        float sum = 0.0f;

        #pragma unroll 16
        for (int k = 0; k < D1; ++k) {
            sum += input[input_idx];
            input_idx += stride;
        }

        output[b * (long long)D2 + d2] = sum;
    }
}

torch::Tensor sum_reduce_dim1(torch::Tensor input) {
    input = input.contiguous();

    int B = input.size(0);
    int D1 = input.size(1);
    int D2 = input.size(2);

    auto output = torch::empty({B, 1, D2}, input.options());

    int threads_per_block = 256;
    int blocks_x = (D2 + threads_per_block - 1) / threads_per_block;
    int blocks_y = B;

    dim3 blocks(blocks_x, blocks_y);
    dim3 threads(threads_per_block);

    sum_reduce_dim1_kernel<<<blocks, threads, 0, 0>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        B, D1, D2
    );

    return output;
}
"""

