#include <hip/hip_runtime.h>
#include <cmath>

#define K0 0.79788456080286535587989f
#define K1 0.044715f

__device__ inline float gelu_tanh_op(float x) {
    float x2 = x * x;
    float inner = K0 * x * (1.0f + K1 * x2);
    return 0.5f * x * (1.0f + tanhf(inner));
}

__global__ void __launch_bounds__(256) gelu_kernel_vec8_tanh(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int vec_size = size / 8;

    if (idx < vec_size) {
        const float4* x_ptr = reinterpret_cast<const float4*>(x);
        float4* out_ptr = reinterpret_cast<float4*>(out);

        int base_idx = idx * 2;
        float4 v1 = x_ptr[base_idx];
        float4 v2 = x_ptr[base_idx + 1];

        float4 r1, r2;

        r1.x = gelu_tanh_op(v1.x);
        r1.y = gelu_tanh_op(v1.y);
        r1.z = gelu_tanh_op(v1.z);
        r1.w = gelu_tanh_op(v1.w);

        r2.x = gelu_tanh_op(v2.x);
        r2.y = gelu_tanh_op(v2.y);
        r2.z = gelu_tanh_op(v2.z);
        r2.w = gelu_tanh_op(v2.w);

        out_ptr[base_idx] = r1;
        out_ptr[base_idx + 1] = r2;
    }
}

__global__ void gelu_kernel_scalar_tanh(const float* __restrict__ x, float* __restrict__ out, int size, int offset) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x + offset;
    if (idx < size) {
        out[idx] = gelu_tanh_op(x[idx]);
    }
}

torch::Tensor gelu_hip(torch::Tensor x) {
    if (!x.is_contiguous()) x = x.contiguous();

    auto size = x.numel();
    auto out = torch::empty_like(x);

    int vec_size = size / 8;
    int remainder = size % 8;

    const int block_size = 256;

    if (vec_size > 0) {
        int num_blocks = (vec_size + block_size - 1) / block_size;
        gelu_kernel_vec8_tanh<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    }

    if (remainder > 0) {
        int offset = vec_size * 8;
        gelu_kernel_scalar_tanh<<<1, remainder>>>(x.data_ptr<float>(), out.data_ptr<float>(), size, offset);
    }

    return out;
}
"""

